-- CREATE DATABASE IF NOT EXISTS orbit_jr CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
-- USE orbit_jr;
-- CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
-- CREATE TABLE profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,headline VARCHAR(255),location VARCHAR(255),years_experience DECIMAL(4,1) DEFAULT 0,target_role VARCHAR(255),resume_text LONGTEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_profiles_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
-- CREATE TABLE skills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,normalized_name VARCHAR(255) NOT NULL,esco_uri VARCHAR(512),skill_type VARCHAR(100),UNIQUE KEY uq_skill_normalized_name(normalized_name));
-- CREATE TABLE profile_skills (profile_id BIGINT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,evidence_text TEXT,evidence_strength DECIMAL(5,4) DEFAULT 0,source VARCHAR(100) DEFAULT 'resume',PRIMARY KEY(profile_id,skill_id),FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
-- CREATE TABLE occupations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,normalized_title VARCHAR(255) NOT NULL,esco_uri VARCHAR(512),description TEXT,INDEX idx_occupation_title(normalized_title));
-- CREATE TABLE occupation_skills (occupation_id BIGINT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,importance DECIMAL(6,4) DEFAULT 0,relation_type VARCHAR(100),PRIMARY KEY(occupation_id,skill_id),FOREIGN KEY(occupation_id) REFERENCES occupations(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
-- CREATE TABLE jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id VARCHAR(255),source VARCHAR(100) NOT NULL,title VARCHAR(500) NOT NULL,company VARCHAR(500),location VARCHAR(500),employment_type VARCHAR(100),work_mode VARCHAR(100),posted_at DATETIME NULL,url VARCHAR(2000),description LONGTEXT NOT NULL,salary_min DECIMAL(14,2),salary_max DECIMAL(14,2),currency VARCHAR(10),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FULLTEXT KEY ft_jobs(title,company,description),INDEX idx_jobs_source(source),INDEX idx_jobs_posted_at(posted_at));
-- CREATE TABLE job_skills (job_id BIGINT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,evidence_text TEXT,evidence_strength DECIMAL(5,4) DEFAULT 0,source VARCHAR(100) DEFAULT 'job_description',PRIMARY KEY(job_id,skill_id),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
-- CREATE TABLE recommendation_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,job_id BIGINT UNSIGNED NOT NULL,event_type ENUM('view','save','apply','dismiss') NOT NULL,position_shown INT,model_version VARCHAR(100),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,INDEX idx_events_profile_created(profile_id,created_at));
-- CREATE TABLE model_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,job_id BIGINT UNSIGNED NOT NULL,lexical_score DOUBLE DEFAULT 0,semantic_score DOUBLE DEFAULT 0,rerank_score DOUBLE DEFAULT 0,market_score DOUBLE DEFAULT 0,calibrated_score DOUBLE DEFAULT 0,evidence_coverage DOUBLE DEFAULT 0,confidence DOUBLE DEFAULT 0,model_version VARCHAR(100) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,INDEX idx_scores_profile(profile_id),INDEX idx_scores_job(job_id));
